"""Fill HWPX training feedback template with JSON data."""

import json
import re
import zipfile
import shutil
import os
from lxml import etree

# Paths
TEMPLATE_PATH = "/root/training_feedback_template.hwpx"
OUTPUT_PATH = "/root/training_feedback_ready.hwpx"
JSON_PATH = "/root/training_feedback.json"
WORK_DIR = "/tmp/hwpx_fill_work"

def load_json_data(path):
    """Load JSON data from file."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def extract_number(value):
    """Extract digits only from a string like '32명' -> '32'."""
    if isinstance(value, (int, float)):
        return str(int(value))
    match = re.search(r'\d+', str(value))
    return match.group(0) if match else str(value)

def format_satisfaction(value):
    """Format satisfaction score as 'X.X점 (5.0점 만점)'."""
    if isinstance(value, (int, float)):
        return f"{float(value):.1f}점 (5.0점 만점)"
    # Try to extract number from strings like "4.5/5.0" or "4.5점"
    match = re.search(r'(\d+\.?\d*)', str(value))
    if match:
        score = float(match.group(1))
        return f"{score:.1f}점 (5.0점 만점)"
    return str(value)

def transform_value(key, value, data):
    """Transform value based on key type."""
    if key == "참석자수":
        return extract_number(value)
    elif key == "만족도":
        return format_satisfaction(value)
    elif key == "종합의견":
        return value + " 후속 심화반 검토 요망."
    else:
        return str(value)

def find_placeholders(text):
    """Find all {{key}} patterns in text."""
    return re.findall(r'\{\{([^}]+)\}\}', text)

def replace_placeholders(text, data):
    """Replace all {{key}} placeholders in text with transformed values."""
    placeholders = find_placeholders(text)
    modified = False
    for key in placeholders:
        if key in data:
            placeholder = f"{{{key}}}"
            new_value = transform_value(key, data[key], data)
            text = text.replace(placeholder, new_value)
            modified = True
    return text, modified

def process_xml_content(xml_bytes, data):
    """Process XML content: replace placeholders and remove lineSegArray from modified paragraphs."""
    # Parse XML preserving encoding
    parser = etree.XMLParser(remove_blank_text=False)
    root = etree.fromstring(xml_bytes, parser)

    # Get namespace map
    nsmap = root.nsmap
    hp_ns = nsmap.get('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

    modified_paras = set()

    # Walk all elements and process text nodes
    for elem in root.iter():
        # Process .text
        if elem.text:
            new_text, modified = replace_placeholders(elem.text, data)
            if modified:
                elem.text = new_text
                # Track parent paragraph for lineSegArray removal
                parent = elem.getparent()
                while parent is not None:
                    if parent.tag == f"{{{hp_ns}}}p" or parent.tag.endswith('}p'):
                        modified_paras.add(parent)
                        break
                    parent = parent.getparent()

        # Process .tail
        if elem.tail:
            new_tail, modified = replace_placeholders(elem.tail, data)
            if modified:
                elem.tail = new_tail
                # Track parent paragraph for lineSegArray removal
                parent = elem.getparent()
                while parent is not None:
                    if parent.tag == f"{{{hp_ns}}}p" or parent.tag.endswith('}p'):
                        modified_paras.add(parent)
                        break
                    parent = parent.getparent()

    # Remove lineSegArray elements from modified paragraphs
    for para in modified_paras:
        for child in list(para):
            tag_name = child.tag
            if tag_name == f"{{{hp_ns}}}lineSegArray" or tag_name.endswith('}lineSegArray'):
                para.remove(child)

    # Serialize back to bytes with XML declaration
    return etree.tostring(root, encoding='utf-8', xml_declaration=True)

def main():
    print("Loading JSON data...")
    data = load_json_data(JSON_PATH)
    print(f"Loaded data: {json.dumps(data, ensure_ascii=False, indent=2)}")

    # Copy template to output
    print(f"\nCopying template to {OUTPUT_PATH}...")
    shutil.copy(TEMPLATE_PATH, OUTPUT_PATH)

    # Clean work directory
    if os.path.exists(WORK_DIR):
        shutil.rmtree(WORK_DIR)
    os.makedirs(WORK_DIR)

    # Extract original ZIP
    print("Extracting HWPX archive...")
    with zipfile.ZipFile(TEMPLATE_PATH, 'r') as zin:
        zin.extractall(WORK_DIR)

    # Process XML files
    xml_files = []
    for root_dir, dirs, files in os.walk(WORK_DIR):
        for fname in files:
            if fname.endswith('.xml'):
                full_path = os.path.join(root_dir, fname)
                rel_path = os.path.relpath(full_path, WORK_DIR)
                xml_files.append(rel_path)

    print(f"\nFound XML files: {xml_files}")

    # Track modified files
    modified_files = {}

    for rel_path in xml_files:
        full_path = os.path.join(WORK_DIR, rel_path)
        with open(full_path, 'rb') as f:
            xml_bytes = f.read()

        # Check if has placeholders
        xml_str = xml_bytes.decode('utf-8')
        if '{{' in xml_str:
            print(f"\nProcessing {rel_path}...")
            new_xml_bytes = process_xml_content(xml_bytes, data)
            modified_files[rel_path] = new_xml_bytes

            # Verify no placeholders remain
            new_xml_str = new_xml_bytes.decode('utf-8')
            if '{{' in new_xml_str:
                print(f"  WARNING: Placeholders still remain in {rel_path}")
            else:
                print(f"  All placeholders replaced successfully")

    # Create new ZIP with modified content
    print(f"\nCreating output archive {OUTPUT_PATH}...")
    with zipfile.ZipFile(TEMPLATE_PATH, 'r') as zin:
        with zipfile.ZipFile(OUTPUT_PATH, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                rel_path = item.filename

                if rel_path in modified_files:
                    # Use modified content
                    zout.writestr(item, modified_files[rel_path])
                    print(f"  Written modified: {rel_path}")
                else:
                    # Copy as-is
                    data_bytes = zin.read(rel_path)
                    zout.writestr(item, data_bytes)

    # Validation
    print("\n" + "="*50)
    print("VALIDATION")
    print("="*50)

    # Re-open and check
    with zipfile.ZipFile(OUTPUT_PATH, 'r') as zout:
        print(f"Is valid ZIP: Yes")

        placeholder_count = 0
        for name in zout.namelist():
            if name.endswith('.xml'):
                content = zout.read(name).decode('utf-8')
                placeholders = re.findall(r'\{\{[^}]+\}\}', content)
                if placeholders:
                    print(f"  WARNING: Found placeholders in {name}: {placeholders}")
                    placeholder_count += len(placeholders)

        if placeholder_count == 0:
            print("All placeholders replaced: Yes")
        else:
            print(f"Remaining placeholders: {placeholder_count}")

    # Extract for detailed verification
    verify_dir = "/tmp/hwpx_verify"
    if os.path.exists(verify_dir):
        shutil.rmtree(verify_dir)
    os.makedirs(verify_dir)

    with zipfile.ZipFile(OUTPUT_PATH, 'r') as zf:
        zf.extractall(verify_dir)

    print("\nDetailed verification:")

    # Check 참석자수 (should be digits only)
    for root_dir, dirs, files in os.walk(verify_dir):
        for fname in files:
            if fname.endswith('.xml'):
                with open(os.path.join(root_dir, fname), 'r', encoding='utf-8') as f:
                    content = f.read()
                    if '참석자' in content:
                        # Find line with 참석자
                        for line in content.split('>'):
                            if '참석자' in line:
                                print(f"  참석자수 line: {line[:100]}...")
                                break
                    if '만족도' in content or '점 (5.0점 만점)' in content:
                        for line in content.split('>'):
                            if '만족도' in line or '점 (5.0점 만점)' in line:
                                print(f"  만족도 line: {line[:150]}...")
                                break
                    if '종합의견' in content or '후속 심화반 검토 요망' in content:
                        for line in content.split('>'):
                            if '종합의견' in line or '후속 심화반 검토 요망' in line:
                                print(f"  종합의견 line: {line[:200]}...")
                                break

    print(f"\nOutput file created: {OUTPUT_PATH}")
    print("Done!")

if __name__ == "__main__":
    main()
